// ---------- shared procedural textures (built once, no external files) ----------
function makeTexture(w, h, draw, rx = 1, ry = 1) {
  const cv = document.createElement('canvas');
  cv.width = w; cv.height = h;
  draw(cv.getContext('2d'), w, h);
  const t = new THREE.CanvasTexture(cv);
  t.colorSpace = THREE.SRGBColorSpace;
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(rx, ry);
  t.anisotropy = renderer.capabilities.getMaxAnisotropy();
  return t;
}
function speckle(g, w, h, rng, base, spread, count) {
  g.fillStyle = base; g.fillRect(0, 0, w, h);
  for (let i = 0; i < count; i++) {
    const v = (rng() * spread) | 0;
    g.fillStyle = `rgba(${v},${v},${v},0.55)`;
    g.fillRect(rng() * w, rng() * h, 1 + rng() * 2, 1 + rng() * 2);
  }
}
const texRng = makeRng(7);
const TEX = {
  asphalt: makeTexture(512, 512, (g, w, h) => speckle(g, w, h, texRng, '#3a3d43', 90, 9000), 1, 1),
  gravel: makeTexture(256, 256, (g, w, h) => speckle(g, w, h, texRng, '#9f947e', 120, 3000), 1, 1),
  concrete: makeTexture(256, 256, (g, w, h) => speckle(g, w, h, texRng, '#b9b6ad', 90, 2000), 1, 1),
};

//@@TRACK@@

