// ---------- race straight: asphalt, paint, curbs, gravel, barriers, poles ----------
function buildTrack(parent) {
  const L = settings.trackLen, hw = TRACK_W / 2;
  const put = (geo, mat, x, y, z, rx = 0) => {
    const m = new THREE.Mesh(geo, mat);
    m.position.set(x, y, z);
    m.rotation.x = rx;
    m.receiveShadow = true;
    parent.add(m);
    return m;
  };
  const flat = -Math.PI / 2;

  TEX.asphalt.repeat.set(L / 6, 1.2);
  put(new THREE.PlaneGeometry(L, TRACK_W),
    new THREE.MeshStandardMaterial({ map: TEX.asphalt, roughness: 0.92, metalness: 0 }),
    0, 0.002, 0, flat);

  // paint (raised a hair above asphalt to avoid z-fight)
  const paint = new THREE.MeshStandardMaterial({ color: 0xf2f2ee, roughness: 0.55, polygonOffset: true, polygonOffsetFactor: -2 });
  for (const s of [-1, 1]) put(new THREE.PlaneGeometry(L, 0.14), paint, 0, 0.004, s * (hw - 0.45), flat);
  for (let x = -L / 2 + 4; x < L / 2 - 3; x += 6) put(new THREE.PlaneGeometry(3, 0.14), paint, x, 0.004, 0, flat);
  put(new THREE.PlaneGeometry(0.4, TRACK_W - 0.9), paint, -L / 2 + 1.6, 0.004, 0, flat);

  // red/white curbs
  const curbTex = makeTexture(64, 16, (g, w, h) => {
    g.fillStyle = '#b8222a'; g.fillRect(0, 0, w / 2, h);
    g.fillStyle = '#f2f2f2'; g.fillRect(w / 2, 0, w / 2, h);
  }, L, 1);
  const curbMat = new THREE.MeshStandardMaterial({ map: curbTex, roughness: 0.7 });
  for (const s of [-1, 1]) {
    const c = new THREE.Mesh(new THREE.BoxGeometry(L, 0.06, 0.5), curbMat);
    c.position.set(0, 0.03, s * (hw + 0.25));
    c.receiveShadow = true; c.castShadow = true;
    parent.add(c);
  }

  // gravel run-off on both sides
  TEX.gravel.repeat.set(L / 3, 1);
  const gravelMat = new THREE.MeshStandardMaterial({ map: TEX.gravel, roughness: 1 });
  for (const s of [-1, 1]) put(new THREE.PlaneGeometry(L, 3), gravelMat, 0, 0.001, s * (hw + 2), flat);

  // concrete barriers
  TEX.concrete.repeat.set(L / 4, 1);
  const concMat = new THREE.MeshStandardMaterial({ map: TEX.concrete, roughness: 0.85 });
  for (const s of [-1, 1]) {
    const b = new THREE.Mesh(new THREE.BoxGeometry(L, 0.9, 0.5), concMat);
    b.position.set(0, 0.45, s * (hw + 4.4));
    b.receiveShadow = true; b.castShadow = true;
    parent.add(b);
  }

  // light poles
  const poleMat = new THREE.MeshStandardMaterial({ color: 0x59606a, metalness: 0.8, roughness: 0.4 });
  const lampMat = new THREE.MeshStandardMaterial({ color: 0xfff3d6, emissive: 0xffe9b0, emissiveIntensity: 2.2 });
  for (let x = -L / 2 + 5; x <= L / 2 - 5; x += 10) {
    for (const s of [-1, 1]) {
      const z = s * (hw + 6.5);
      const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.16, 10, 10), poleMat);
      pole.position.set(x, 5, z);
      pole.castShadow = true;
      parent.add(pole);
      const head = new THREE.Mesh(new THREE.BoxGeometry(1.4, 0.12, 0.4), lampMat);
      head.position.set(x, 9.9, z - s * 0.4);
      parent.add(head);
    }
  }
}
//@@TRACK@@

