// ---------- physics: cannon-es world, materials, fixed-step driver ----------
let world = null, mats = null;
let accum = 0, simTime = 0;

function makeWorld() {
  const w = new CANNON.World({ gravity: new CANNON.Vec3(0, -settings.gravity, 0) });
  w.broadphase = new CANNON.SAPBroadphase(w);
  w.solver.iterations = 12;
  w.allowSleep = true;
  w.defaultContactMaterial.friction = 0.5;
  w.defaultContactMaterial.restitution = 0.1;

  const m = {
    ground: new CANNON.Material('ground'),
    brick: new CANNON.Material('brick'),
    car: new CANNON.Material('car'),
  };
  const pair = (a, b, friction, restitution) =>
    w.addContactMaterial(new CANNON.ContactMaterial(a, b, { friction, restitution }));
  pair(m.brick, m.brick, settings.brickFriction, settings.brickRest);
  pair(m.brick, m.ground, settings.groundFriction, settings.brickRest);
  pair(m.brick, m.car, settings.brickFriction, 0.15);
  pair(m.car, m.ground, settings.groundFriction, 0.1);
  pair(m.car, m.car, 0.4, 0.1);

  const g = new CANNON.Body({
    type: CANNON.Body.STATIC, mass: 0, material: m.ground, shape: new CANNON.Plane(),
    collisionFilterGroup: BIT_GROUND, collisionFilterMask: ALL_BITS,
  });
  g.quaternion.setFromEuler(-Math.PI / 2, 0, 0);
  w.addBody(g);
  return { w, m };
}

// per-step hooks (filled in by the car and wall systems)
function preStep(dt) {}
function postStep(dt) {}

function stepPhysics(dt) {
  if (state.paused || !world) return;
  accum += dt * state.timeScale;
  let n = 0;
  while (accum >= PHYS_DT && n < MAX_STEPS) {
    preStep(PHYS_DT);
    world.step(PHYS_DT);
    postStep(PHYS_DT);
    accum -= PHYS_DT;
    simTime += PHYS_DT;
    n++;
  }
  if (n === MAX_STEPS) accum = 0; // hitch: drop backlog instead of spiralling
}
