// ---------- brick wall: staggered running bond, every brick is a rigid body ----------
const MORTAR = 0.012;   // visual gap only; physics bricks touch exactly
const wallFaceX = () => settings.trackLen / 2 - WALL_SETBACK;
let run = null;         // per-run container: group, wall, car, shards, fx

const _m4 = new THREE.Matrix4(), _q = new THREE.Quaternion(), _p = new THREE.Vector3();
const _one = new THREE.Vector3(1, 1, 1);
function syncInstanced(mesh, bodies) {
  for (let i = 0; i < bodies.length; i++) {
    const b = bodies[i];
    _p.set(b.position.x, b.position.y, b.position.z);
    _q.set(b.quaternion.x, b.quaternion.y, b.quaternion.z, b.quaternion.w);
    mesh.setMatrixAt(i, _m4.compose(_p, _q, _one));
  }
  mesh.instanceMatrix.needsUpdate = true;
}

function buildWall(parent) {
  const s = settings;
  const bw = s.brickW, bh = s.brickH, bd = s.brickD;
  const faceX = wallFaceX();
  const rng = makeRng(RUN_SEED ^ 0x9e37);
  const bodies = [];

  for (let r = 0; r < s.wallRows; r++) {
    for (let d = 0; d < s.wallDepth; d++) {
      for (let c = 0; c < s.wallCols; c++) {
        const b = new CANNON.Body({
          mass: s.brickMass, material: mats.brick,
          shape: new CANNON.Box(new CANNON.Vec3(bw / 2, bh / 2, bd / 2)),
          collisionFilterGroup: BIT_BRICK, collisionFilterMask: ALL_BITS,
          linearDamping: 0.01, angularDamping: 0.02,
        });
        // running bond: odd courses shifted half a brick
        const z = -s.wallCols * bw / 2 + bw * (c + 0.5) + (r % 2 ? bw / 2 : 0);
        b.position.set(faceX + bd * (d + 0.5), bh * (r + 0.5), z);
        world.addBody(b);
        bodies.push(b);
      }
    }
  }

  const mesh = new THREE.InstancedMesh(
    new THREE.BoxGeometry(bw - MORTAR, bh - MORTAR, bd - MORTAR),
    new THREE.MeshStandardMaterial({ map: TEX.brick, roughness: 0.9, metalness: 0 }),
    bodies.length
  );
  const col = new THREE.Color();
  for (let i = 0; i < bodies.length; i++) {
    const v = 0.8 + rng() * 0.32;
    mesh.setColorAt(i, col.setRGB(v, v * (0.9 + rng() * 0.1), v * 0.86));
  }
  mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  mesh.frustumCulled = false;
  parent.add(mesh);
  run.wall = { bodies, mesh };
  syncInstanced(mesh, bodies);
}
//@@WALL@@

