const pairKey = (i, j) => (i < j ? i * 64 + j : j * 64 + i);

// pivot given in world space -> body-local frame
function localPivot(body, wp) {
  const q = body.quaternion;
  const d = new CANNON.Vec3(wp.x - body.position.x, wp.y - body.position.y, wp.z - body.position.z);
  const out = new CANNON.Vec3();
  new CANNON.Quaternion(-q.x, -q.y, -q.z, q.w).vmult(d, out);
  return out;
}

// parts that overlap at spawn (or are bonded) must not collide, otherwise the car explodes on frame 1
function halfAABB(p) {
  const d = p.dims, q = p.body.quaternion;
  if (p.wheel) return [d[0], d[1], d[2]];
  const ang = 2 * Math.atan2(q.z, q.w);     // only the windshield is rotated (about z)
  const c = Math.abs(Math.cos(ang)), s = Math.abs(Math.sin(ang));
  return [c * d[0] + s * d[1], s * d[0] + c * d[1], d[2]];
}
function overlapAtRest(p, q) {
  const a = halfAABB(p), b = halfAABB(q), e = 0.002;
  const pa = p.body.position, pb = q.body.position;
  return Math.abs(pa.x - pb.x) < a[0] + b[0] - e &&
         Math.abs(pa.y - pb.y) < a[1] + b[1] - e &&
         Math.abs(pa.z - pb.z) < a[2] + b[2] - e;
}

function linkCar(car) {
  const byName = {};
  for (const p of car.parts) byName[p.name] = p;
  const P = (x, y, z) => new CANNON.Vec3(car.originStart + x * car.sx, y * car.sy, z * car.sz);
  car.bondCount = new Map();
  car.permIgnore = new Set();

  for (const [an, bn, pts, limit, kind] of BOND_SPEC) {
    const A = byName[an], B = byName[bn];
    const k = pairKey(A.idx, B.idx);
    for (const pt of pts) {
      const wp = P(pt[0], pt[1], pt[2]);
      const con = new CANNON.PointToPointConstraint(
        A.body, localPivot(A.body, wp), B.body, localPivot(B.body, wp), 1e8);
      world.addConstraint(con);
      car.bonds.push({
        a: A.idx, b: B.idx, con, limit, alive: true,
        kind: kind || 'joint', glassPart: kind === 'glass' ? B : null,
      });
      car.bondCount.set(k, (car.bondCount.get(k) || 0) + 1);
    }
  }
  for (let i = 0; i < car.parts.length; i++) {
    for (let j = i + 1; j < car.parts.length; j++) {
      if (overlapAtRest(car.parts[i], car.parts[j])) car.permIgnore.add(pairKey(i, j));
    }
  }
  refreshMasks(car);
}

// a pair ignores collisions while bonded or while it was interpenetrating at rest
function refreshMasks(car) {
  for (const p of car.parts) {
    if (!p.alive) continue;
    let ignore = 0;
    for (const q of car.parts) {
      if (q === p || !q.alive) continue;
      const k = pairKey(p.idx, q.idx);
      if (car.permIgnore.has(k) || (car.bondCount.get(k) || 0) > 0) ignore |= carBit(q.idx);
    }
    p.body.collisionFilterMask = ALL_BITS & ~ignore;
  }
}

// constraint force in N: solver multiplier (impulse per step) / dt, with a separation fallback
function bondForce(bond, h) {
  const eqs = bond.con.equations;
  if (eqs.length && typeof eqs[0].multiplier === 'number') {
    let s = 0;
    for (const e of eqs) s += e.multiplier * e.multiplier;
    return Math.sqrt(s) / h;
  }
  const pa = bond.con.bodyA.pointToWorldFrame(bond.con.pivotA);
  const pb = bond.con.bodyB.pointToWorldFrame(bond.con.pivotB);
  return pa.distanceTo(pb) * 1e7;
}

