function releasePart(car, part) {
  for (const b of car.bonds) {
    if (b.alive && (b.a === part.idx || b.b === part.idx)) breakBond(car, b);
  }
}

function postStep(dt) {
  if (!run || !run.car) return;
  const car = run.car;
  for (const bond of car.bonds) {
    if (!bond.alive) continue;
    if (bondForce(bond, dt) > bond.limit) breakBond(car, bond);
  }
}
