// ---------- glass: a broken pane is replaced by a grid of rigid shards ----------
const SHARD_CELL = 0.2;
const DIRS = [new THREE.Vector3(1, 0, 0), new THREE.Vector3(0, 1, 0), new THREE.Vector3(0, 0, 1)];

function shatterGlass(car, part) {
  if (!part || !part.alive) return;
  part.alive = false;
  releasePart(car, part);
  world.removeBody(part.body);
  part.obj.removeFromParent();

  const d = part.dims, q = part.body.quaternion, c = part.body.position;
  const k = d.indexOf(Math.min(...d));              // thin axis = pane normal
  const ua = (k + 1) % 3, ub = (k + 2) % 3;
  const na = Math.max(2, Math.round((2 * d[ua]) / SHARD_CELL));
  const nb = Math.max(2, Math.round((2 * d[ub]) / SHARD_CELL));
  const ca = (2 * d[ua]) / na, cb = (2 * d[ub]) / nb;
  const thick = 0.008;
  const mass = part.mass / (na * nb);
  const toWorld = (v) => q.vmult(v, new CANNON.Vec3());
  const nLocal = new CANNON.Vec3(); nLocal.setComponent ? 0 : 0;
  const n = new CANNON.Vec3(); n.set(0, 0, 0);
  const local = new CANNON.Vec3();
  [local.x, local.y, local.z] = [0, 0, 0];
  const axis = [new CANNON.Vec3(1, 0, 0), new CANNON.Vec3(0, 1, 0), new CANNON.Vec3(0, 0, 1)];
  toWorld(axis[k]).vsub(new CANNON.Vec3(0, 0, 0), n);
  // outward sign: away from the cabin centre
  const cab = car.parts[1].body.position;
  const outward = ((c.x - cab.x) * n.x + (c.y - cab.y) * n.y + (c.z - cab.z) * n.z) >= 0 ? 1 : -1;
  const rng = run.rng;

  for (let i = 0; i < na; i++) {
    for (let j = 0; j < nb; j++) {
      const half = [0, 0, 0];
      half[ua] = ca * 0.45; half[ub] = cb * 0.45; half[k] = thick;
      const off = [0, 0, 0];
      off[ua] = -d[ua] + ca * (i + 0.5);
      off[ub] = -d[ub] + cb * (j + 0.5);
      const wo = toWorld(new CANNON.Vec3(off[0], off[1], off[2]));
      const pos = new CANNON.Vec3(c.x + wo.x + n.x * 0.03 * outward, c.y + wo.y + n.y * 0.03 * outward, c.z + wo.z + n.z * 0.03 * outward);
      const sp = 2 + rng() * 2.5;
      const tan = (rng() - 0.5) * 1.5;
      const vel = new CANNON.Vec3(
        part.body.velocity.x + n.x * sp * outward + tan,
        part.body.velocity.y + n.y * sp * outward + rng() * 0.8,
        part.body.velocity.z + n.z * sp * outward - tan);
      const sb = new CANNON.Body({
        mass, material: mats.car, quaternion: q.clone(), position: pos,
        shape: new CANNON.Box(new CANNON.Vec3(half[0], half[1], half[2])),
        collisionFilterGroup: BIT_DEBRIS, collisionFilterMask: ALL_BITS,
        linearDamping: 0.02, angularDamping: 0.05,
      });
      sb.velocity.copy(vel);
      sb.angularVelocity.set((rng() - 0.5) * 12, (rng() - 0.5) * 12, (rng() - 0.5) * 12);
      world.addBody(sb);
      const mesh = new THREE.Mesh(new THREE.BoxGeometry(2 * half[0], 2 * half[1], 2 * half[2]), CAR_MAT.glass);
      mesh.castShadow = true;
      run.group.add(mesh);
      run.shards.push({ body: sb, mesh });
    }
  }
}

function syncShards() {
  for (const s of run.shards) {
    const b = s.body;
    s.mesh.position.set(b.position.x, b.position.y, b.position.z);
    s.mesh.quaternion.set(b.quaternion.x, b.quaternion.y, b.quaternion.z, b.quaternion.w);
  }
}
