// ---------- drive: constant push on every part until the bumper reaches the wall ----------
const ZERO = new CANNON.Vec3();
function preStep(dt) {
  if (!run || !run.car) return;
  const car = run.car;
  const cabin = car.parts[1];                        // cabin is the reference body
  const carX = cabin.body.position.x + 0.1 * car.sx; // car centre estimate
  if (car.driving && carX >= car.originImpact - 0.02) car.driving = false;

  if (car.driving) {
    for (const p of car.parts) {
      if (p.alive) p.body.applyForce(new CANNON.Vec3(car.accel * p.mass, 0, 0), ZERO);
    }
  }

  if (!car.impacted) {
    const front = car.parts.find((p) => p.name === 'bumperF');
    if (front.body.position.x + 0.07 * car.sx >= wallFaceX() - 0.02) {
      car.impacted = true;
      car.impactTime = simTime;
      car.impactSpeed = -cabin.body.velocity.x;
      onImpact(car);
    }
  }
}

