// ---------- run lifecycle: Replay and Apply rebuild the whole run from current settings ----------
function buildRun() {
  if (run) {
    scene.remove(run.group);
    run.group.traverse((o) => { if (o.geometry) o.geometry.dispose(); });
  }
  const made = makeWorld();
  world = made.w;
  mats = made.m;
  accum = 0;
  simTime = 0;
  run = { group: new THREE.Group(), rng: makeRng(RUN_SEED), shards: [], wall: null, car: null };
  scene.add(run.group);
  buildTrack(run.group);
  buildWall(run.group);
  buildCar(run.group);
  resetFx();
  state.runCount++;
}

buildRun();
//@@END@@

