// ---------- FX: dust, sparks, skid marks, contact blobs (visual only, sim-time driven) ----------
const fxTex = {
  dust: makeTexture(64, 64, (g, w, h) => {
    const gr = g.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
    gr.addColorStop(0, 'rgba(255,255,255,0.9)'); gr.addColorStop(1, 'rgba(255,255,255,0)');
    g.fillStyle = gr; g.fillRect(0, 0, w, h);
  }),
  blob: makeTexture(64, 64, (g, w, h) => {
    const gr = g.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
    gr.addColorStop(0, 'rgba(0,0,0,0.8)'); gr.addColorStop(0.5, 'rgba(0,0,0,0.4)'); gr.addColorStop(1, 'rgba(0,0,0,0)');
    g.fillStyle = gr; g.fillRect(0, 0, w, h);
  }),
};
const SKID_MAX = 600, BLOB_CAP = 512;
let fx = null;

function makeParticles(n, material, drag, g) {
  const geo = new THREE.BufferGeometry();
  const pos = new Float32Array(n * 3);
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3).setUsage(THREE.DynamicDrawUsage));
  const obj = new THREE.Points(geo, material);
  obj.frustumCulled = false;
  return { obj, pos, vel: new Float32Array(n * 3), life: new Float32Array(n), n, head: 0, drag, g };
}
function emit(ps, x, y, z, vx, vy, vz, life) {
  const i = ps.head;
  ps.head = (ps.head + 1) % ps.n;
  ps.pos.set([x, y, z], i * 3);
  ps.vel.set([vx, vy, vz], i * 3);
  ps.life[i] = life;
}
function stepParticles(ps, sdt) {
  for (let i = 0; i < ps.n; i++) {
    if (ps.life[i] <= 0) continue;
    const o = i * 3;
    ps.life[i] -= sdt;
    if (ps.life[i] <= 0) { ps.pos[o + 1] = -1000; continue; }
    const damp = Math.exp(-ps.drag * sdt);
    ps.vel[o] *= damp;
    ps.vel[o + 1] = ps.vel[o + 1] * damp - ps.g * sdt;
    ps.vel[o + 2] *= damp;
    ps.pos[o] += ps.vel[o] * sdt;
    ps.pos[o + 1] += ps.vel[o + 1] * sdt;
    ps.pos[o + 2] += ps.vel[o + 2] * sdt;
    if (ps.pos[o + 1] < 0.03) { ps.pos[o + 1] = 0.03; ps.vel[o + 1] = 0; }
  }
  ps.obj.geometry.attributes.position.needsUpdate = true;
}

function resetFx() {
  const dustMat = new THREE.PointsMaterial({ map: fxTex.dust, color: 0xd6c6a2, size: 1.7, transparent: true, opacity: 0.6, depthWrite: false });
  const sparkMat = new THREE.PointsMaterial({ color: 0xffb450, size: 0.07, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false });
  const skidGeo = new THREE.BufferGeometry();
  skidGeo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(SKID_MAX * 18), 3).setUsage(THREE.DynamicDrawUsage));
  skidGeo.setDrawRange(0, 0);
  const skid = new THREE.Mesh(skidGeo, new THREE.MeshBasicMaterial({ color: 0x080808, transparent: true, opacity: 0.6, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -4 }));
  skid.frustumCulled = false;
  const blobs = new THREE.InstancedMesh(new THREE.PlaneGeometry(1, 1),
    new THREE.MeshBasicMaterial({ map: fxTex.blob, transparent: true, depthWrite: false }), BLOB_CAP);
  blobs.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
  blobs.frustumCulled = false;
  fx = {
    dust: makeParticles(400, dustMat, 1.4, -0.4),
    sparks: makeParticles(160, sparkMat, 0.5, 9.8),
    skid, skidCount: 0, skidHead: 0, skidPrev: [null, null, null, null],
    blobs, lastSim: 0, impactSim: -1,
  };
  run.group.add(fx.dust.obj, fx.sparks.obj, skid, blobs);
  shakeAmp = 0;
}

const _bq = new THREE.Quaternion().setFromEuler(new THREE.Euler(-Math.PI / 2, 0, 0));
const _bm = new THREE.Matrix4(), _bp = new THREE.Vector3(), _bs = new THREE.Vector3();
function syncBlobs() {
  let k = 0;
  const put = (b) => {
    if (k >= BLOB_CAP) return;
    const lift = Math.max(0, 1 - b.position.y / 1.6);
    const r = Math.max(0.12, b.boundingRadius * 0.9) * lift;
    _bp.set(b.position.x, 0.006, b.position.z);
    _bs.set(2 * r, 2 * r, 1);
    fx.blobs.setMatrixAt(k++, _bm.compose(_bp, _bq, _bs));
  };
  if (run.wall) for (const b of run.wall.bodies) put(b);
  for (const p of run.car.parts) if (p.alive) put(p.body);
  for (const s of run.shards) put(s.body);
  fx.blobs.count = k;
  fx.blobs.instanceMatrix.needsUpdate = true;
}

// one skid quad per frame per sliding wheel, laid on the ground
function addSkid(x0, z0, x1, z1) {
  const dx = x1 - x0, dz = z1 - z0;
  const len = Math.hypot(dx, dz);
  if (len < 1e-4) return;
  const hw = 0.11, px = (-dz / len) * hw, pz = (dx / len) * hw, y = 0.007;
  const v = [
    x0 + px, y, z0 + pz, x0 - px, y, z0 - pz, x1 + px, y, z1 + pz,
    x0 - px, y, z0 - pz, x1 - px, y, z1 - pz, x1 + px, y, z1 + pz,
  ];
  const arr = fx.skid.geometry.attributes.position.array;
  arr.set(v, fx.skidHead * 18);
  fx.skidHead = (fx.skidHead + 1) % SKID_MAX;
  fx.skidCount = Math.min(SKID_MAX, fx.skidCount + 1);
  fx.skid.geometry.setDrawRange(0, fx.skidCount * 6);
  fx.skid.geometry.attributes.position.needsUpdate = true;
}

function onImpact(car) {
  shakeAmp = 0.5;
  fx.impactSim = simTime;
  const bumper = car.parts.find((p) => p.name === 'bumperF').body.position;
  for (let i = 0; i < 160; i++) {
    const r = fx.dust.n ? makeRng(i * 7919 + 13)() : 0.5;   // deterministic per particle, visual only
    emit(fx.dust, bumper.x + 0.1, 0.2 + r * 0.6, bumper.z + (r - 0.5) * 4,
