#bar{position:fixed;left:50%;bottom:14px;transform:translateX(-50%);display:flex;gap:8px;align-items:center;padding:8px 10px;background:rgba(12,14,18,.74);backdrop-filter:blur(6px);border-radius:12px;border:1px solid rgba(255,255,255,.12);font-size:13px;white-space:nowrap;user-select:none;max-width:calc(100vw - 20px);overflow-x:auto}
#bar button,#panel button{background:rgba(255,255,255,.08);color:#eef;border:1px solid rgba(255,255,255,.16);border-radius:8px;padding:6px 10px;font:inherit;cursor:pointer}
#bar button:hover,#panel button:hover{background:rgba(255,255,255,.18)}
#bar button.on{background:#e8452c;border-color:#e8452c;color:#fff}
.seg{display:flex;gap:2px}
.seg button{border-radius:6px}
#stat{opacity:.8;font-variant-numeric:tabular-nums;padding-left:6px}
