#panel[hidden]{display:none}
#panel h3{margin:4px 0 6px;font-size:15px}
#panel .grp{margin:14px 0 4px;font-size:11px;letter-spacing:.12em;text-transform:uppercase;opacity:.6}
#panel label{display:flex;justify-content:space-between;align-items:center;gap:10px;margin:5px 0}
#panel input{width:104px;background:#0b0d11;color:#eef;border:1px solid rgba(255,255,255,.22);border-radius:6px;padding:5px 7px;font:inherit}
#panel .row{display:flex;gap:8px;margin-top:16px}
#panel .row button{flex:1}
#panel .pri,#bar .pri{background:#e8452c;border-color:#e8452c;color:#fff}
#panel p{opacity:.6;font-size:12px;line-height:1.4;margin:6px 0 0}
