buildRun();
applyView();

// ---------- UI: control bar, settings panel, keyboard ----------
const $ = (id) => document.getElementById(id);
const fields = [...document.querySelectorAll('#panel input[data-k]')];
const LIMITS = {
  speed: [1, 60], carMass: [100, 10000], carLen: [2.5, 8], carWid: [1, 3], carHgt: [0.6, 3],
  wallCols: [1, 30], wallRows: [1, 20], wallDepth: [1, 4], brickMass: [0.1, 50],
  brickW: [0.1, 1.5], brickH: [0.05, 1], brickD: [0.05, 1],
  gravity: [0, 30], brickFriction: [0, 2], brickRest: [0, 1], groundFriction: [0, 2], trackLen: [24, 80],
};
const INTS = new Set(['wallCols', 'wallRows', 'wallDepth']);

function fillPanel() {
  for (const el of fields) el.value = settings[el.dataset.k];
}
// every field is clamped and written into settings; nothing on screen is decorative
function readPanel() {
  for (const el of fields) {
    const k = el.dataset.k;
    let v = parseFloat(el.value);
    if (!Number.isFinite(v)) v = settings[k];
    v = Math.min(LIMITS[k][1], Math.max(LIMITS[k][0], v));
    if (INTS.has(k)) v = Math.round(v);
    settings[k] = v;
    el.value = v;
  }
}
function updatePlayBtn() {
  $('btnPlay').textContent = state.paused ? 'Play' : 'Pause';
}
function togglePause() {
  state.paused = !state.paused;
  updatePlayBtn();
}
function replay() {
  buildRun();
  state.paused = false;
  updatePlayBtn();
  applyView();
  highlight();
}
function highlight() {
  document.querySelectorAll('#speeds button').forEach((b) => b.classList.toggle('on', +b.dataset.speed === state.timeScale));
  document.querySelectorAll('#views button').forEach((b) => b.classList.toggle('on', b.dataset.view === state.view));
}

document.querySelectorAll('#speeds button').forEach((b) =>
  b.addEventListener('click', () => { state.timeScale = +b.dataset.speed; highlight(); }));
document.querySelectorAll('#views button').forEach((b) =>
  b.addEventListener('click', () => { setView(b.dataset.view); highlight(); }));
$('btnPlay').addEventListener('click', togglePause);
$('btnReplay').addEventListener('click', replay);
$('btnSettings').addEventListener('click', () => { $('panel').hidden = !$('panel').hidden; });
$('btnApply').addEventListener('click', () => { readPanel(); replay(); });
$('btnDefaults').addEventListener('click', () => { Object.assign(settings, DEFAULTS); fillPanel(); replay(); });
document.querySelectorAll('button').forEach((b) => b.addEventListener('click', () => b.blur()));

addEventListener('keydown', (e) => {
  if (document.activeElement && document.activeElement.tagName === 'INPUT') return;
  if (e.code === 'Space') { e.preventDefault(); if (!e.repeat) togglePause(); }
  const views = ['impact', 'follow', 'top', 'orbit'];
  if (e.key >= '1' && e.key <= '4') { setView(views[+e.key - 1]); highlight(); }
});

let hudTimer = 0;
function updateHud(dt) {
  hudTimer -= dt;
  if (hudTimer > 0 || !run || !run.car) return;
  hudTimer = 0.15;
  const car = run.car;
  const parts = [`t ${simTime.toFixed(2)} s`, `${state.paused ? 'paused' : state.timeScale + '×'}`];
  parts.push(`${car.breakCount || 0} bonds broken`, `${run.shards.length} shards`);
  if (car.impacted) parts.push(`impact ${car.impactSpeed.toFixed(1)} m/s`);
  $('stat').textContent = parts.join(' · ');
}

fillPanel();
highlight();
updatePlayBtn();
//@@END@@

