// sky dome with a horizon gradient, plus aerial fog so the track fades into distance
const sky = new THREE.Mesh(
  new THREE.SphereGeometry(450, 32, 16),
  new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    uniforms: {
      top: { value: new THREE.Color(0x3f74b8) },
      horizon: { value: new THREE.Color(0xe3ecf4) },
      bottom: { value: new THREE.Color(0x6d8756) },
    },
    vertexShader: `varying vec3 vDir;
      void main() { vDir = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }`,
    fragmentShader: `uniform vec3 top; uniform vec3 horizon; uniform vec3 bottom; varying vec3 vDir;
      void main() {
        float h = vDir.y;
        vec3 c = h > 0.0 ? mix(horizon, top, smoothstep(0.0, 0.45, h)) : mix(horizon, bottom, smoothstep(0.0, 0.2, -h));
        gl_FragColor = vec4(pow(c, vec3(1.0 / 2.2)), 1.0);
      }`,
  })
);
scene.add(sky);
scene.fog = new THREE.Fog(0xc9d9e8, 160, 420);

